public class CustomerWorkflowImpl implements CustomerWorkflow {
    @Override
    public void execute(CustomerData data) {
        // BUG: Non-deterministic call inside workflow logic breaks event replay
        String correlationId = UUID.randomUUID().toString();
        long startTime = System.currentTimeMillis();

        Activities.chargeUser(data.getUserId(), data.getAmount());
        Activities.provisionAccount(data.getUserId());
    }
}

